-- 设置隔离级别
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

-- 查看当前隔离级别
SELECT @@transaction_isolation;

-- MVCC可见性判断伪代码
function isVisible(trx_id, readView) {
    if (trx_id < readView.min_trx_id) return true;
    if (trx_id >= readView.max_trx_id) return false;
    if (readView.m_ids.contains(trx_id)) return false;
    return true;
}

-- 如果不可见，沿undo log版本链查找可见版本
